class Node:
    def __init__(self, value):
        self.value = value
        self.children = []

def tree(li):
    nodes = [Node(i) for i in li]
    for i in range(1, len(li)):
        nodes[(i - 1) // 2].children.append(nodes[i])
    return nodes[0]

def leaf_sum(node):
    if node is None:
        return 0
    if not node.children:
        return node.value
    return sum(leaf_sum(c) for c in node.children)

li = [3, 5, 8, 12, 15, 18, 21]

root = tree(li)

print(leaf_sum(root))

public class Main {
    static int calls = 0;
    static int fib(int n) {
        calls++;
        if (n <= 1) return n;
        return fib(n - 1) + fib(n - 2);
    }
    public static void main(String[] args) {
        fib(6);
        System.out.println(calls);
    }
}

